const SCOPE = new URL(self.registration.scope);
const PREFIX = `ordex-static:${SCOPE.pathname}:`;
const CACHE = `${PREFIX}${MANIFEST.version}`;
const FILES = new Set(MANIFEST.files.map((f) => new URL(f, SCOPE).pathname));

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      try {
        await cache.addAll(MANIFEST.files.map((f) => new Request(new URL(f, SCOPE), { cache: 'reload', credentials: 'omit' })));
      } catch (err) {
        await caches.delete(CACHE);
        throw err;
      }
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
      await self.clients.claim();
    })()
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'ORDEX_SW_SKIP_WAITING') self.skipWaiting();
  if (event.data === 'ORDEX_SW_STATUS' && event.ports[0]) {
    caches
      .open(CACHE)
      .then((c) => c.keys())
      .then((keys) => event.ports[0].postMessage({ version: MANIFEST.version, revision: MANIFEST.revision, cached: keys.length, total: MANIFEST.files.length }));
  }
});

function pageFor(pathname) {
  const p = pathname.endsWith('/') ? `${pathname}index.html` : pathname;
  return FILES.has(p) ? p : null;
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || req.headers.has('authorization')) return;
  const url = new URL(req.url);
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  const rel = url.pathname.slice(SCOPE.pathname.length);
  if (rel.startsWith('api/') || rel === 'mcp' || rel.startsWith('mcp/')) return;

  if (req.mode === 'navigate') {
    const cachedPath = pageFor(url.pathname);
    event.respondWith(
      fetch(req).catch(async () => {
        const hit = cachedPath && (await caches.match(cachedPath, { cacheName: CACHE }));
        if (hit) return hit;
        return new Response(
          `<!doctype html><meta charset="utf-8"><title>Offline</title><p>You are offline and ${url.pathname} is not saved for offline use.</p><p><a href="${SCOPE.pathname}">Open the saved home page</a></p>`,
          { status: 503, headers: { 'content-type': 'text/html; charset=utf-8' } }
        );
      })
    );
    return;
  }
  if (!FILES.has(url.pathname)) return;
  event.respondWith(caches.match(url.pathname, { cacheName: CACHE }).then((hit) => hit || fetch(req)));
});
